internal sealed partial class UnattendedTestRunner
{
    private static void AssertTaskCardIdentityContract(CombatRootSnapshot root,
        MegaCrit.Sts2.Core.Entities.Players.Player player,
        MegaCrit.Sts2.Core.Combat.CombatState live)
    {
        using IDisposable isolation = SimulationNotificationIsolation.Enter();
        var parent = root.ForkSimulator();
        string before = DescribeContinuationContractState(parent, root, player);
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        CardModel sample = parent.State.GetPlayerCombatState(player).Hand.Cards[0].Preview;
        CardModel Fresh() => PredictionUtils.CloneCardStateForSimulation(sample);
        int cases = 0;
        void Require(bool condition, string message)
        {
            if (!condition) throw new InvalidOperationException(message);
            cases++;
        }

        CardModel original = Fresh();
        PredictedCard wrapper = new(original);
        PredictedCard duplicate = new(original);
        PredictedCard generatedSame = new(original, original);
        CardModel preview = Fresh();
        PredictedCard withPreview = new(original, preview);
        Require(wrapper.References(preview) && duplicate.References(preview)
            && generatedSame.References(preview) && withPreview.References(original),
            "null/same/existing preview registration differs");
        wrapper.MaterializePreview();
        Require(withPreview.References(wrapper.Preview) && !ReferenceEquals(wrapper.Preview, original),
            "materialization did not keep the original identity");
        PredictedCard wrapperClone = withPreview.Clone();
        PredictedCard gameplayClone = withPreview.CreateClone();
        Require(withPreview.References(wrapperClone.Preview) && wrapperClone.References(original)
            && !withPreview.References(gameplayClone.Preview) && !gameplayClone.References(original),
            "wrapper/gameplay clone identity distinction differs");

        CardModel otherOriginal = Fresh();
        PredictedCard other = new(otherOriginal);
        bool conflicted = false;
        try { _ = new PredictedCard(otherOriginal, preview); }
        catch (InvalidOperationException error) when (error.Message ==
            "A card preview belongs to a different combat-card identity.") { conflicted = true; }
        Require(conflicted && withPreview.References(preview) && !other.References(preview),
            "conflict did not preserve the first identity");

        int RunConcurrent(bool sameOriginal)
        {
            CardModel sharedPreview = Fresh();
            CardModel[] originals = Enumerable.Range(0,16).Select(_ => sameOriginal ? original : Fresh()).ToArray();
            PredictedCard[] registered = originals.Select(card => new PredictedCard(card)).ToArray();
            PredictedCard?[] results = new PredictedCard?[16];
            InvalidOperationException?[] errors = new InvalidOperationException?[16];
            using CountdownEvent ready = new(16);
            using ManualResetEventSlim start = new(false);
            Thread[] threads = Enumerable.Range(0,16).Select(index => new Thread(() =>
            {
                ready.Signal();
                start.Wait();
                try { results[index] = new PredictedCard(originals[index], sharedPreview); }
                catch (InvalidOperationException error) { errors[index] = error; }
            }) { IsBackground = true }).ToArray();
            foreach (Thread thread in threads) thread.Start();
            bool allReady = ready.Wait(TimeSpan.FromSeconds(10));
            start.Set();
            foreach (Thread thread in threads)
                if (!thread.Join(TimeSpan.FromSeconds(10)))
                    throw new InvalidOperationException("card identity registration thread did not drain");
            Require(allReady, "registration workers did not overlap");
            int successes = results.Count(result => result is not null);
            Require(successes == (sameOriginal ? 16 : 1), "concurrent registration winner count differs");
            Require(errors.All(error => error is null || error.Message ==
                "A card preview belongs to a different combat-card identity."), "unexpected concurrent failure");
            for (int index = 0; index < 16; index++)
                Require(registered[index].References(sharedPreview) == (sameOriginal || results[index] is not null),
                    "concurrent registration changed the winning identity");
            return successes;
        }
        int sameIdentitySuccesses = RunConcurrent(true);
        int differentIdentitySuccesses = RunConcurrent(false);

        // Own each mutable branch and use the same notification isolation as real workers.
        var children = Enumerable.Range(0,16).Select(_ => parent.Fork()).ToArray();
        Parallel.For(0,children.Length,index =>
        {
            using IDisposable workerIsolation = SimulationNotificationIsolation.Enter();
            var child = children[index];
            if (DescribeContinuationContractState(child, root, player) != before)
                throw new InvalidOperationException("identity sibling initial state/history/RNG differs");
            var hand = child.State.GetPlayerCombatState(player).Hand.Cards;
            CardModel rootIdentity = hand[0].Original;
            hand[0].MutablePreview.GiveSingleTurnRetain();
            hand[1].MaterializePreview();
            _ = hand[2].MutablePreview;
            hand[2].EnableAttachedModelForkIsolation();
            string changed = DescribeContinuationContractState(child, root, player);
            var grandchild = child.Fork();
            var grandHand = grandchild.State.GetPlayerCombatState(player).Hand.Cards;
            if (changed == before || DescribeContinuationContractState(grandchild, root, player) != changed
                || !hand[0].References(grandHand[0].Preview) || !grandHand[0].References(rootIdentity)
                || !hand[2].References(grandHand[2].Preview)
                || ReferenceEquals(hand[2].Preview, grandHand[2].Preview))
                throw new InvalidOperationException("identity or external-attachment Fork differs");
            grandHand[0].MutablePreview.GiveSingleTurnSly();
            if (DescribeContinuationContractState(child, root, player) != changed
                || DescribeContinuationContractState(grandchild, root, player) == changed
                || ReferenceEquals(hand[0].Preview, grandHand[0].Preview))
                throw new InvalidOperationException("identity grandchild mutation contaminated parent");
        });
        Require(DescribeContinuationContractState(parent, root, player) == before
            && ContinuationStamp.CaptureLive(live).StateText == liveBefore,
            "card identity proof changed parent or live state");

        // Allocation observation of exact old/new registration only; no wall-time claim.
        var table = (ConditionalWeakTable<CardModel, object>)typeof(PredictedCard)
            .GetField("CardIdentities",BindingFlags.Static | BindingFlags.NonPublic)!.GetValue(null)!;
        var register = typeof(PredictedCard).GetNestedType("PreviewStorage",BindingFlags.NonPublic)!
            .GetMethod("RegisterIdentity",BindingFlags.Static | BindingFlags.NonPublic)!
            .CreateDelegate<Func<CardModel,CardModel?,object?,object>>();
        object known = table.GetValue(original, static _ => new object());
        object Old(CardModel card, CardModel? model, object? ignored)
        {
            object identity = table.GetValue(card,static _ => new object());
            if (model is not null && !ReferenceEquals(table.GetValue(model,_ => identity),identity))
                throw new InvalidOperationException("A card preview belongs to a different combat-card identity.");
            return identity;
        }
        Func<CardModel,CardModel?,object?,object> old = Old;
        long Measure(Func<CardModel,CardModel?,object?,object> action, CardModel? model, object? cached)
        {
            for (int index=0;index<4096;index++) _ = action(original,model,cached);
            long bytes = GC.GetAllocatedBytesForCurrentThread();
            for (int index=0;index<10000;index++) _ = action(original,model,cached);
            return GC.GetAllocatedBytesForCurrentThread() - bytes;
        }
        var allocations = new List<object>();
        foreach (var item in new (string Name,CardModel? Preview,object? Known)[] {
            ("null-preview",null,null), ("same-instance",original,null),
            ("registered-preview",preview,null), ("known-COW-identity",preview,known) })
        {
            long oldBytes=Measure(old,item.Preview,item.Known);
            long candidateBytes=Measure(register,item.Preview,item.Known);
            Require(candidateBytes == 0 && oldBytes > 0, "registration allocation removal not observed");
            allocations.Add(new { item.Name, calls=10000, oldBytes, candidateBytes });
        }
        var evidence = new { cases, sameIdentitySuccesses, differentIdentitySuccesses,
            siblingCount=16, forkGenerations=2, fullStateHistoryNineRngParentLive=true,
            allocations, allocationScope="exact old/new warm registration; not complete request or RSS" };
        string json=JsonSerializer.Serialize(evidence,new JsonSerializerOptions {WriteIndented=true});
        File.WriteAllText("/home/ltlly/Code/nmslmod/CombatSolver-common-state-cost-20261005/.local/tool-tasks/card-identity-callback-roi-20261009/native-identity-proof.json",json);
        Entry.Logger.Info("[CombatSolver/Test] CARD_IDENTITY_CONTRACT "+json);
    }
}

using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using CombatSolver.Engine.Common;
namespace CombatSolver;
internal static class TaskForkIdentityMapProof
{
    private sealed class IdentityOnly
    {
        public override bool Equals(object? value) => throw new InvalidOperationException("virtual Equals was called");
        public override int GetHashCode() => throw new InvalidOperationException("virtual hash was called");
    }
    internal static void Verify()
    {
        Type type = typeof(PredictionForkContext);
        FieldInfo hint = type.GetField("_entryCountHint", BindingFlags.Static | BindingFlags.NonPublic)!;
        int beforeHint = (int)hint.GetValue(null)!;
        MethodInfo bucket = type.GetMethod("GetBucket", BindingFlags.Static | BindingFlags.NonPublic)!;
        int cases = 0, operations = 0, checks = 0, bucketChecks = 0;
        try
        {
            object[] hashes = Enumerable.Range(0, 1024).Select(_ => (object)new IdentityOnly()).ToArray();
            int[] lengths = [1,2,3,7,16,31,32,63,64,127,128,257,1024,int.MaxValue,int.MinValue,-1];
            foreach (object source in hashes)
                foreach (int length in lengths)
                {
                    int expected = (int)((uint)RuntimeHelpers.GetHashCode(source) % (uint)length);
                    int actual = (int)bucket.Invoke(null, [source, length])!;
                    if (actual != expected) throw new InvalidOperationException("bucket differs from modulo oracle");
                    bucketChecks++;
                }
            try { bucket.Invoke(null, [hashes[0], 0]); throw new InvalidOperationException("zero length did not fail"); }
            catch (TargetInvocationException error) when (error.InnerException is DivideByZeroException) { bucketChecks++; }
            foreach (int initialHint in new[] {0,40,63,64,65,512})
            foreach (int count in new[] {0,1,39,40,48,63,64,65,96,97,128,513,4097})
            {
                hint.SetValue(null, initialHint);
                using PredictionForkContext context = new();
                Dictionary<object, object> oracle = new(ReferenceEqualityComparer.Instance);
                List<object> sources = [];
                for (int index = 0; index < count; index++)
                {
                    object source = new IdentityOnly(), fork = new IdentityOnly();
                    if (context.TryRemap(source, out object? unexpected) || unexpected is not null)
                        throw new InvalidOperationException("new source unexpectedly mapped");
                    context.Register(source, fork); oracle.Add(source, fork); sources.Add(source); operations++;
                    context.Register(source, fork); operations++;
                    object self = new IdentityOnly(); context.Register(self, self); operations++;
                    if (!ReferenceEquals(context.RemapOrSelf(self), self)) throw new InvalidOperationException("self mapping changed");
                    if (!context.TryRemap(source, out object? actual) || !ReferenceEquals(actual, fork)
                        || !ReferenceEquals(context.RequireRemap(source), fork)
                        || !ReferenceEquals(context.RemapOrSelf(source), fork))
                        throw new InvalidOperationException("new mapping is not the exact fork");
                    checks += 4;
                    if (index < 130 || index % 127 == 0)
                    {
                        foreach ((object prior, object target) in oracle)
                        {
                            if (!context.TryRemap(prior, out object? remapped) || !ReferenceEquals(remapped, target))
                                throw new InvalidOperationException("mapping lost across resize/collision");
                            checks++;
                        }
                    }
                }
                if (sources.Count > 0)
                {
                    object source = sources[count / 2];
                    try { context.Register(source, new IdentityOnly()); throw new InvalidOperationException("conflicting fork admitted"); }
                    catch (InvalidOperationException error) when (error.Message.Contains("was forked twice", StringComparison.Ordinal)) { checks++; }
                    if (!ReferenceEquals(context.RequireRemap(source), oracle[source])) throw new InvalidOperationException("conflict changed prior mapping");
                }
                object absent = new IdentityOnly();
                if (context.TryRemap(absent, out object? missing) || missing is not null || !ReferenceEquals(context.RemapOrSelf(absent), absent))
                    throw new InvalidOperationException("absent lookup changed");
                try { context.RequireRemap(absent); throw new InvalidOperationException("missing mapping admitted"); }
                catch (InvalidOperationException error) when (error.Message.Contains("has no fork mapping", StringComparison.Ordinal)) { checks++; }
                context.Register<object>(null!, null!);
                context.Register<object>(null!, absent);
                if (!ReferenceEquals(context.RequireRemap<object>(null!), absent)) throw new InvalidOperationException("null identity mapping differs");
                // A nested context cannot reuse this parent's mutable mappings.
                using (PredictionForkContext nested = new())
                {
                    foreach (object source in sources.Take(16))
                    {
                        object target = new IdentityOnly(); nested.Register(source, target);
                        if (!ReferenceEquals(context.RequireRemap(source), oracle[source])
                            || !ReferenceEquals(nested.RequireRemap(source), target))
                            throw new InvalidOperationException("nested context contaminated parent");
                        checks += 2;
                    }
                }
                cases++;
            }
            // Force one long probe chain, crossing the 3/4 growth boundary.
            hint.SetValue(null,64);
            using (PredictionForkContext collisions = new())
            {
                var selected = new List<(object Source,object Fork)>();
                while (selected.Count < 60)
                {
                    object source = new IdentityOnly();
                    if (((uint)RuntimeHelpers.GetHashCode(source) & 255) == 0)
                    {
                        object target = new IdentityOnly(); selected.Add((source,target)); collisions.Register(source,target);
                    }
                }
                foreach (var pair in selected)
                    if (!ReferenceEquals(collisions.RequireRemap(pair.Source),pair.Fork))
                        throw new InvalidOperationException("collision chain lost mapping");
                checks += selected.Count; operations += selected.Count; cases++;
            }
            Entry.Logger.Info("[CombatSolver/Test] FORK_IDENTITY_MAP " + JsonSerializer.Serialize(new {
                cases, operations, checks, bucketChecks,
                scope = "reference identity/modulo oracle; collisions, growth, duplicate/conflict/self/null, nested ownership; no performance timing"
            }));
        }
        finally { hint.SetValue(null,beforeHint); }
    }
}
